import time
import sys
import signal
from gpiozero import DigitalOutputDevice

# Define GPIO pins
GPIO_PINS = [2, 3, 4]

# Function to handle SIGINT (Ctrl+C)
def signal_handler(sig, frame):
    print("Program interrupted. Cleaning up GPIO resources...")
    cleanup()
    sys.exit(1)

# Function to initialize GPIO pins
def initialize_gpios():
    gpios = []
    for pin in GPIO_PINS:
        try:
            gpio = DigitalOutputDevice(pin, active_high=True)
            gpios.append(gpio)
        except RuntimeError as e:
            print(f"Error initializing GPIO {pin}: {e}")
            cleanup()
            sys.exit(1)
    return gpios

# Function to cleanup GPIO resources
def cleanup():
    for gpio in gpios:
        try:
            gpio.close()
        except Exception as e:
            print(f"Error closing GPIO {gpio.pin}: {e}")

# Main program
if __name__ == "__main__":
    # Register signal handler for SIGINT
    signal.signal(signal.SIGINT, signal_handler)

    # Initialize GPIO pins
    gpios = initialize_gpios()

    if gpios:
        try:
            while True:
                # Toggle GPIO states
                for gpio in gpios:
                    gpio.value = not gpio.value

                # Print the state of each GPIO
                print(" ".join(str(gpio.value) for gpio in gpios))

                # Wait for 60 seconds
                time.sleep(60)
        except Exception as e:
            print(f"An error occurred: {e}")
            cleanup()
            sys.exit(1)
    else:
        print("No GPIO devices found. Exiting.")
        sys.exit(1)

